import Foundation

// Native home for the runtime-support types that used to be generated by the
// Rust UniFFI layer (`Generated/pipette_ios.swift`). The iOS benchmark path is
// now fully native Swift over llama.cpp / MLX, so these live here and are shared
// by `MLXRuntime`, the llama runner, and the job/headless plumbing — no Rust FFI.

/// Failures surfaced by a benchmark runtime (llama.cpp or MLX) — shared so both
/// engines fail a cell the same way and the readiness gate can throw one type.
/// `formatJobError` turns `.outOfMemory` into the actionable "smaller quant /
/// model / context length" hint.
enum RuntimeError: LocalizedError, Equatable {
    /// Benchmark type not supported on this runtime (e.g. `vl_throughput` on MLX).
    case unsupported(String)
    /// The readiness gate reported the run was cancelled.
    case cancelled
    /// The readiness gate timed out; carries the observed condition.
    case readiness(String)
    /// An engine operation failed (load / tokenize / decode / template); the detail
    /// string carries the runtime-specific context.
    case engine(String)
    /// Allocation failed for lack of memory — classified from the captured engine log.
    case outOfMemory(String)

    var errorDescription: String? {
        switch self {
        case .unsupported(let id):     return "Benchmark '\(id)' is not supported on this runtime."
        case .cancelled:               return "Run cancelled."
        case .readiness(let observed): return "Device not ready: \(observed)."
        case .engine(let detail):      return "Engine error: \(detail)."
        case .outOfMemory(let detail): return "Out of memory: \(detail)."
        }
    }
}

/// A unit of intra-cell benchmark progress — *what* advanced, not how to show it.
/// The runtimes report these as work completes; the presentation decision (which
/// to surface, the label, whether to move the progress bar) is made by the UI
/// layer (`JobExecutor`). This mirrors the granularity the Rust kernel reports:
/// throughput counts measured attempts, eval counts dataset samples.
enum BenchmarkProgress: Equatable {
    /// One measured rep of a throughput benchmark finished (`completed` of `total`).
    case attempt(completed: Int, total: Int)
    /// One eval dataset sample finished (`completed` of `total`).
    case sample(completed: Int, total: Int)
}

// MARK: - Native device probes (formerly Rust FFI free functions)

/// Max SoC die temperature in C, or a non-positive value when unavailable.
/// Backed by the ObjC `pipette_soc_temp` (IOHID thermal sensors), declared in the
/// bridging header. The private read is gated by the `PIPETTE_PRIVATE_THERMAL`
/// build flag in the ObjC translation unit.
nonisolated func socTemp() -> Double {
    pipette_soc_temp()
}

/// A bound path that names nothing on disk. The crate's `require_file` bail: an ensure or a
/// bind that half-completed would otherwise surface as an engine load failure naming a file
/// no one wrote.
nonisolated struct BoundPathMissing: Error, Equatable, LocalizedError {
    let what: String
    let path: String

    var errorDescription: String? {
        "bound \(what) is not a file: \(path) (ensure/bind may be incomplete)"
    }
}

/// The engine was handed a model of another format. A construction bug — `Engine` routes by
/// format — so it names what it got rather than guessing a recovery.
nonisolated struct UnexpectedBoundModel: Error, Equatable, LocalizedError {
    let expected: String
    let got: String

    var errorDescription: String? {
        "expected bound \(expected) (after ensureModel/bindUnder), got \(got)"
    }
}
